import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
        except StopIteration:
            break

        adj = [[] for _ in range(N + 1)]
        for i in range(2, N + 1):
            p = int(next(iterator))
            adj[p].append(i)

        stack = [1]
        order = []
        while stack:
            u = stack.pop()
            order.append(u)
            for v in adj[u]:
                stack.append(v)

        sz = [0] * (N + 1)
        for u in reversed(order):
            s = 1
            for v in adj[u]:
                s += sz[v]
            sz[u] = s

        dp = [0] * (N + 1)
        for u, s in zip(order, sz):
            if s == 1:
                dp[u] = 1
            else:
                best = 0
                for v in adj[u]:
                    if dp[v] > best:
                        best = dp[v]
                dp[u] = best + 1

        total = sum(dp[1:])
        results.append(str(total))

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
